// 미로: '1'은 지나갈 수 있는 칸. (0,0)에서 (R-1,C-1)까지 지나는 칸 수의 최솟값(시작·끝 칸 포함)
d[0][0] = 1; q.push({0, 0});
while (!q.empty()) {
    auto [x, y] = q.front(); q.pop();
    for (int k = 0; k < 4; k++) {
        int a = x + dx[k], b = y + dy[k];
        if (0 <= a && a < R && 0 <= b && b < C && g[a][b] == '1' && d[a][b] == 0) {
            d[a][b] = d[x][y] + 1;
            q.push({a, b});
        }
    }
}
// 답은 d[R-1][C-1] (0이면 갈 수 없음)
